"use client";

import { useEffect, useState } from "react";
import type { AnimationCode, AnimationItem } from "@/lib/types";

const componentCodeCache = new Map<string, Promise<AnimationCode>>();

/**
 * CSS items already carry their code. Component items fetch it on demand from
 * /r/<id>.json (generated by scripts/build-registry.ts), then cache it.
 */
export function loadAnimationCode(item: AnimationItem): Promise<AnimationCode> {
  if (item.source === "css") {
    return Promise.resolve({
      dependencies: [],
      files: [
        { name: "styles.css", language: "css", code: item.css },
        { name: "index.html", language: "html", code: item.html },
      ],
    });
  }

  let pending = componentCodeCache.get(item.id);
  if (!pending) {
    pending = fetch(`/r/${item.id}.json`)
      .then((response) => {
        if (!response.ok) throw new Error(`Could not load code for "${item.id}" (${response.status})`);
        return response.json() as Promise<AnimationCode>;
      })
      .catch((error) => {
        componentCodeCache.delete(item.id); // allow a retry
        throw error;
      });
    componentCodeCache.set(item.id, pending);
  }
  return pending;
}

export function getInstallCommand(dependencies: string[]): string | null {
  return dependencies.length > 0 ? `npm install ${dependencies.join(" ")}` : null;
}

type CodeState =
  | { status: "idle" | "loading" }
  | { status: "ready"; code: AnimationCode }
  | { status: "error"; message: string };

/** Pass `null` while the code panel is closed; the fetch starts when an item is passed. */
export function useAnimationCode(item: AnimationItem | null): CodeState {
  const [state, setState] = useState<CodeState>({ status: "idle" });

  useEffect(() => {
    if (!item) {
      setState({ status: "idle" });
      return;
    }

    let isCancelled = false;
    setState({ status: "loading" });
    loadAnimationCode(item)
      .then((code) => !isCancelled && setState({ status: "ready", code }))
      .catch((error: Error) => !isCancelled && setState({ status: "error", message: error.message }));

    return () => {
      isCancelled = true;
    };
  }, [item]);

  return state;
}
